package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the wall clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at rate tokens per second,
// up to capacity.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive capacity or rate.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). If clock is nil, the real clock is used.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed now, consuming them
// if so. n must be non-negative; a negative n returns false.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (lazy-refilled).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.tokens += l.clock.Now().Sub(l.last).Seconds() * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = l.clock.Now()
	return l.tokens
}
