	ErrRate      = errors.New("ratelimit: rate must be > 0")
	ErrBurst     = errors.New("ratelimit: burst must be > 0")
	ErrNilClock  = errors.New("ratelimit: clock must not be nil")
	ErrNegativeN = errors.New("ratelimit: n must be >= 0")
)

// New creates a Limiter with the given refill rate (tokens per second),
// burst capacity, and starting tokens. If clock is nil, the real clock is used.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrRate
	}
	if burst <= 0 {
		return nil, ErrBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   now,
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
